import React, {useState} from 'react';
import {Cursor} from "react-creative-cursor";
import {Button, Checkbox, Flex, Form, Input, message, Modal} from "antd";
import ModalChangePassword from "../modal_change password/modal_change_password";

const ModalProfile = (props) => {

    const [form] = Form.useForm();

    const handleOkAuth = () => {
        props.setIsModalProfileOpen(true);
    };

    const handleCancelAuth = () => {
        props.setIsModalProfileOpen(false);
    };

    const [isPasswordModalVisible, setIsPasswordModalVisible] = useState(false);

    const onFinish = async (values) => {
        console.log('Received values:', values);
        // Здесь можно отправить данные на сервер
        message.success('Информация успешно обновлена!');
        handleCancelAuth();
    };

    const handlePasswordChange = async (values) => {
        console.log('Password change values:', values);
        // Здесь можно отправить запрос на сервер для смены пароля
        message.success('Пароль успешно изменен!');
        setIsPasswordModalVisible(false);
    };


    return (
                <Modal
                    open={props.isModalProfileOpen}
                    onOk={handleOkAuth}
                    data-cursor-exclusion
                    title="Профиль"
                    onCancel={handleCancelAuth}
                    footer={null}
                >
                    <Cursor
                        cursorSize={20}
                        animationDuration={.3}
                        cursorBackgrounColor={'#000'}
                        isGelly={true}
                        gellyAnimationAmount={10}
                    />
                    <Form
                        form={form}
                        name="user_info"
                        onFinish={onFinish}
                        initialValues={{
                            remember: true,
                        }}
                    >
                        <Form.Item
                            name="phone"
                            label="Номер телефона"
                            rules={[
                                {
                                    required: true,
                                    message: 'Пожалуйста, введите номер телефона!',
                                },
                            ]}
                        >
                            <Input />
                        </Form.Item>
                        <Form.Item
                            name="company"
                            label="Название компании"
                            rules={[
                                {
                                    required: true,
                                    message: 'Пожалуйста, введите название компании!',
                                },
                            ]}
                        >
                            <Input />
                        </Form.Item>
                        <Form.Item
                            name="backupEmail"
                            label="Резервный email"
                            rules={[
                                {
                                    type: 'email',
                                    message: 'Некорректный адрес электронной почты!',
                                },
                                {
                                    required: true,
                                    message: 'Пожалуйста, введите резервный email!',
                                },
                            ]}
                        >
                            <Input />
                        </Form.Item>
                        <Form.Item>
                            <Button type="primary" htmlType="submit">
                                Сохранить
                            </Button>
                            <Button
                                type="link"
                                onClick={() => setIsPasswordModalVisible(true)}
                            >
                                Сменить пароль
                            </Button>
                        </Form.Item>
                    </Form>
                    <ModalChangePassword isPasswordModalVisible={isPasswordModalVisible} setIsPasswordModalVisible={setIsPasswordModalVisible}/>
                </Modal>





    );
};

export default ModalProfile;